require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$u=current_user();$s=db()->prepare('SELECT st.*,b.name branch_name,se.name semester_name,dv.name division_name FROM students st LEFT JOIN branches b ON b.id=st.branch_id LEFT JOIN semesters se ON se.id=st.semester_id LEFT JOIN divisions dv ON dv.id=st.division_id WHERE st.user_id=?');$s->execute([$u['id']]);$st=$s->fetch();$att=db()->prepare('SELECT ROUND(100*SUM(a.status="Present")/NULLIF(COUNT(*),0),2) FROM attendance a WHERE a.student_id=?');$att->execute([$st['id']]);$fees=db()->prepare('SELECT COALESCE(SUM(amount-paid_amount),0) FROM student_fees WHERE student_id=?');$fees->execute([$st['id']]);page_top('My Digital Campus');?><div class='hero'><div><span class='pill'>DIGITAL STUDENT ID</span><h2>Good day, <?=e($u['name'])?>.</h2><p><?=e($st['enrollment_no'])?> · <?=e($st['branch_name'])?> · <?=e($st['semester_name'])?> · Division <?=e($st['division_name'])?></p></div><a class='btn btn-light' href='certificates.php'>Digital documents</a></div><div class='row g-3'><?php kpi('Attendance',($att->fetchColumn()??0).'%','◉');kpi('Fee Balance','₹'.number_format((float)$fees->fetchColumn(),2),'₹');kpi('Assignments',db()->query("SELECT COUNT(*) FROM assignments WHERE deadline>=NOW() AND status='published'")->fetchColumn(),'✓');kpi('Upcoming Exams',db()->query("SELECT COUNT(*) FROM exams WHERE exam_date>=CURDATE() AND status='scheduled'")->fetchColumn(),'▣');?></div><div class='row g-4 mt-1'><div class='col-lg-7'><div class='card p-4'><h5>Academic Command Center</h5><div class='d-flex gap-2 flex-wrap'><a class='btn btn-outline-primary' href='academics.php'>Academics</a><a class='btn btn-outline-primary' href='attendance.php'>Attendance</a><a class='btn btn-outline-primary' href='assignments.php'>Assignments</a><a class='btn btn-outline-primary' href='results.php'>Results</a><a class='btn btn-outline-primary' href='fees.php'>Fees</a></div></div></div><div class='col-lg-5'><div class='card p-4'><h5>AI College Assistant</h5><p>Ask authorized questions about your campus data.</p><a class='btn btn-primary' href='ai.php'>Open AI Assistant</a></div></div></div><?php page_bottom();